  CustomProcessorResult,
  SingleFileToolOperationConfig,
  MultiFileToolOperationConfig,
  CustomToolOperationConfig,
  ProcessingProgress,
  ResponseHandler,
} from "@app/hooks/tools/shared/toolOperationTypes";

export {
  ToolType,
  defineSingleFileTool,
  defineMultiFileTool,
  defineCustomTool,
};
export type {
  ToolOperationConfig,
  ToolOperationHook,
  CustomProcessorResult,
  SingleFileToolOperationConfig,
  MultiFileToolOperationConfig,
  CustomToolOperationConfig,
  ProcessingProgress,
  ResponseHandler,
};

// Re-export for backwards compatibility
export { createStandardErrorHandler } from "@app/utils/toolErrorHandler";

/**
 * Shared hook for tool operations providing consistent error handling, progress tracking,
 * and FileContext integration. Eliminates boilerplate while maintaining flexibility.
 *
 * Supports three tool patterns, selected by the config's toolType:
 * 1. Single-file tools (ToolType.singleFile): processes files individually
 * 2. Multi-file tools (ToolType.multiFile): single API call with all files
 * 3. Complex tools (ToolType.custom): customProcessor takes full control
 *
 * @param config - Tool operation configuration
 * @returns Hook interface with state and execution methods
 */
export const useToolOperation = <TParams>(
  config: ToolOperationConfig<TParams>,
): ToolOperationHook<TParams> => {
  const { t } = useTranslation();
  const { addFiles, consumeFiles, undoConsumeFiles, selectors } =
    useFileContext();
  const { actions: navActions } = useNavigationActions();
  const viewerContext = useContext(ViewerContext);
  const setActiveFileId = viewerContext?.setActiveFileId ?? (() => {});

  // Composed hooks
  const { state, actions } = useToolState();
  const { actions: fileActions } = useFileContext();
  const { processFiles, cancelOperation: cancelApiCalls } =
    useToolApiCalls<TParams>();
  const {
    generateThumbnails,
    createDownloadInfo,
    cleanupBlobUrls,
    extractZipFiles,
  } = useToolResources();

  // Determine endpoint for cloud usage check and credit routing.
  // For function endpoints, use defaultParameters to get a representative static value.
  const endpointString = config.endpoint
    ? typeof config.endpoint === "function"
      ? config.defaultParameters
        ? (config.endpoint(config.defaultParameters) ?? undefined)
        : undefined
      : config.endpoint
    : undefined;

  const { checkCredits } = useCreditCheck(config.operationType, endpointString);
  const willUseCloud = useWillUseCloud(endpointString);
  const continueResolutions = useResolutionContinuation();
  const notificationsAvailable = useNotificationsAvailable();
  const onToolRunComplete = useToolRunComplete();

  // Track last operation for undo functionality
  const lastOperationRef = useRef<{
    inputFiles: File[];
    inputStirlingFileStubs: StirlingFileStub[];
    outputFileIds: FileId[];
  } | null>(null);

  /**
   * Record a failure and keep what a retry needs. Shared with the batch's per-input failures:
   * one bad file in twenty is still a failure the user has to be told about.
   */
  const reportFailure = useCallback(
    (
      error: unknown,
      fileIds: FileId[],
      runtimeEndpoint: string | undefined,
      params: TParams,
    ) => {
import { useEffect, useCallback, useRef } from "react";
import { useEndpointEnabled } from "@app/hooks/useEndpointConfig";
import { useViewScopedFiles } from "@app/hooks/tools/shared/useViewScopedFiles";
import { BaseToolProps } from "@app/types/tool";
import { ToolOperationHook } from "@app/hooks/tools/shared/useToolOperation";
import { BaseParametersHook } from "@app/hooks/tools/shared/useBaseParameters";
import { StirlingFile } from "@app/types/fileContext";

interface BaseToolReturn<
  TParams,
  TParamsHook extends BaseParametersHook<TParams>,
> {
  // File management
  selectedFiles: StirlingFile[];

  // Tool-specific hooks
  params: TParamsHook;
  operation: ToolOperationHook<TParams>;

  // Endpoint validation
  endpointEnabled: boolean | null;
  endpointLoading: boolean;

  // Standard handlers
  handleExecute: () => Promise<void>;
  handleThumbnailClick: (file: File) => void;
  handleSettingsReset: () => void;
  handleUndo: () => Promise<void>;

  // Standard computed state
  hasFiles: boolean;
  hasResults: boolean;
  settingsCollapsed: boolean;
