// Root Vitest config so the Storybook addon-vitest Testing UI (and a bare
// `vitest` run from frontend/) discovers the Storybook browser-test project.
// The project definition lives in .storybook/vitest.config.ts; this re-exports
// it from the conventional root location. The editor unit tests are separate
// (editor/vitest.config.ts, run with `vitest --root editor`).
// oxlint-disable-next-line no-restricted-imports -- config re-export; no @-alias covers .storybook/
export { default } from "./.storybook/vitest.config";
import { defineConfig } from "vitest/config";
import react from "@vitejs/plugin-react-swc";
import tsconfigPaths from "vite-tsconfig-paths";
// oxlint-disable-next-line no-restricted-imports -- config runs in node, before the aliases exist
import { iconSvgr } from "./scripts/icons/svgrOptions.mts";

// Projects do NOT inherit the root test.testTimeout, so every project silently
// ran at vitest's 5s default. Spread this into each one instead.
const TIMEOUTS = { testTimeout: 10000, hookTimeout: 10000 };

export default defineConfig({
  test: {
    globals: true,
    environment: "jsdom",
    setupFiles: ["./src/core/setupTests.ts"],
    css: false,
    exclude: [
      "node_modules/",
      "src/**/*.spec.ts", // Exclude Playwright E2E tests
      "src/tests/test-fixtures/**",
    ],
    ...TIMEOUTS,
    coverage: {
      reporter: ["text", "json", "html"],
      exclude: [
        "node_modules/",
        "src/core/setupTests.ts",
        "src/proprietary/setupTests.ts",
        "src/saas/setupTests.ts",
        "**/*.d.ts",
        "src/tests/test-fixtures/**",
        "src/**/*.spec.ts",
      ],
    },
    projects: [
      {
        test: {
          name: "core",
          ...TIMEOUTS,
          include: ["src/core/**/*.test.{ts,tsx}"],
